-- Theory questions for MTH 211. Safe to run twice.
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Relations$q$, $q$Define an equivalence relation. Show that congruence modulo n is an equivalence relation on the integers.$q$, 5, $q$A relation R on a set is an equivalence relation if it is reflexive (a R a), symmetric (a R b implies b R a) and transitive (a R b and b R c imply a R c). Define a = b (mod n) to mean n divides (a - b). Reflexive: a - a = 0 is divisible by n. Symmetric: if n divides (a - b) then n divides (b - a) = -(a - b). Transitive: if n divides (a - b) and (b - c) then n divides their sum (a - b) + (b - c) = a - c. So congruence modulo n is an equivalence relation.$q$, $q$[{"t":"Definition: reflexive, symmetric and transitive","m":2},{"t":"Proves reflexive","m":1},{"t":"Proves symmetric","m":1},{"t":"Proves transitive","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define an equivalence relation. Show that congruence modulo n is an equivalence relation on the integers.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Relations$q$, $q$Explain what an equivalence class is. List the equivalence classes of congruence modulo 3 on the integers and say what they form.$q$, 5, $q$The equivalence class of a is the set of all elements related to a. For congruence modulo 3: [0] = {..., -6, -3, 0, 3, 6, ...}, [1] = {..., -5, -2, 1, 4, 7, ...} and [2] = {..., -4, -1, 2, 5, 8, ...}. These three classes do not overlap and together contain every integer, so they form a partition of the integers.$q$, $q$[{"t":"Definition of an equivalence class","m":1},{"t":"Class [0]","m":1},{"t":"Class [1]","m":1},{"t":"Class [2]","m":1},{"t":"Partition (disjoint and covering)","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Explain what an equivalence class is. List the equivalence classes of congruence modulo 3 on the integers and say what they form.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Algebraic structures$q$, $q$State the axioms of a group. Show that the set of integers under addition is a group.$q$, 5, $q$A group is a set G with a binary operation that satisfies: closure (a * b is in G), associativity ((a * b) * c = a * (b * c)), an identity element e with a * e = e * a = a, and an inverse for every element a, an element b with a * b = b * a = e. For the integers under addition: the sum of two integers is an integer (closure). Addition is associative. The identity is 0 because a + 0 = a. The inverse of a is -a because a + (-a) = 0. So the integers form a group under addition.$q$, $q$[{"t":"Four group axioms stated","m":2},{"t":"Closure and associativity checked","m":1},{"t":"Identity 0","m":1},{"t":"Inverse -a","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the axioms of a group. Show that the set of integers under addition is a group.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Algebraic structures$q$, $q$Prove that the identity element of a group is unique.$q$, 5, $q$Suppose e and e' are both identity elements of a group G. Since e is an identity, e * e' = e'. Since e' is an identity, e * e' = e. So e = e * e' = e', which means e = e'. Therefore the identity is unique.$q$, $q$[{"t":"Assumes two identities e and e'","m":1},{"t":"Uses e as identity to get e * e' = e'","m":1},{"t":"Uses e' as identity to get e * e' = e","m":1},{"t":"Concludes e = e'","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Prove that the identity element of a group is unique.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Algebraic structures$q$, $q$State the subgroup test. Show that the set of even integers is a subgroup of the integers under addition.$q$, 5, $q$A non-empty subset H of a group G is a subgroup if for all a and b in H, a * b^-1 is in H (in additive notation, a - b is in H). Let H be the even integers. H is not empty because 0 is in H. Take two even integers a = 2m and b = 2n. Then a - b = 2m - 2n = 2(m - n), which is even, so a - b is in H. By the subgroup test H is a subgroup of the integers.$q$, $q$[{"t":"Subgroup test stated","m":2},{"t":"H is non-empty","m":1},{"t":"Takes a = 2m and b = 2n","m":1},{"t":"Shows a - b = 2(m - n) is even","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the subgroup test. Show that the set of even integers is a subgroup of the integers under addition.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Rings and fields$q$, $q$Define a ring, an integral domain and a field. Explain why the integers are an integral domain but not a field, and why the integers modulo 5 form a field.$q$, 5, $q$A ring is a set with addition and multiplication where addition makes it an abelian group, multiplication is associative, and multiplication distributes over addition. An integral domain is a commutative ring with unity and no zero divisors. A field is a commutative ring with unity in which every non-zero element has a multiplicative inverse. The integers have no zero divisors, so they form an integral domain, but 2 has no integer inverse (there is no integer x with 2x = 1), so they are not a field. In the integers modulo 5 every non-zero element has an inverse: 1 x 1 = 1, 2 x 3 = 6 = 1, 4 x 4 = 16 = 1. So it is a field.$q$, $q$[{"t":"Ring defined","m":1},{"t":"Integral domain defined","m":1},{"t":"Field defined","m":1},{"t":"Integers: no inverse for 2","m":1},{"t":"Integers mod 5: inverses shown","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define a ring, an integral domain and a field. Explain why the integers are an integral domain but not a field, and why the integers modulo 5 form a field.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Homomorphisms$q$, $q$Define a homomorphism and its kernel. Show that the mapping from the integers to the integers modulo n given by x maps to x mod n is a homomorphism and find its kernel.$q$, 5, $q$A homomorphism between groups is a mapping f with f(a + b) = f(a) + f(b). Its kernel is the set of elements mapped to the identity. Let f(x) = x mod n. Then f(a + b) = (a + b) mod n = (a mod n) + (b mod n) mod n = f(a) + f(b), so f is a homomorphism. The identity of the integers mod n is 0. An integer x maps to 0 exactly when n divides x. So the kernel is nZ, the set of all multiples of n.$q$, $q$[{"t":"Definition of a homomorphism","m":1},{"t":"Definition of the kernel","m":1},{"t":"Verifies f(a + b) = f(a) + f(b)","m":2},{"t":"Kernel is the multiples of n","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define a homomorphism and its kernel. Show that the mapping from the integers to the integers modulo n given by x maps to x mod n is a homomorphism and find its kernel.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Methods of proof$q$, $q$Describe the direct method, the contrapositive method and proof by contradiction. Prove by the contrapositive that if n^2 is even then n is even.$q$, 5, $q$In a direct proof we start from the assumption and reach the conclusion by valid steps. In a proof by the contrapositive we prove not q implies not p instead of p implies q, since they are equivalent. In a proof by contradiction we assume the statement is false and reach an impossible result. For the claim, the contrapositive is: if n is odd then n^2 is odd. Let n = 2k + 1. Then n^2 = 4k^2 + 4k + 1 = 2(2k^2 + 2k) + 1, which is odd. So the contrapositive is true, and hence if n^2 is even then n is even.$q$, $q$[{"t":"Describes the three methods","m":2},{"t":"States the contrapositive","m":1},{"t":"Takes n = 2k + 1 and squares","m":1},{"t":"Shows n^2 is odd and concludes","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Describe the direct method, the contrapositive method and proof by contradiction. Prove by the contrapositive that if n^2 is even then n is even.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 211$q$, $q$Sets, Logic and Algebra$q$, $q$Number systems$q$, $q$State the Euclidean algorithm and use it to find the greatest common divisor of 84 and 36.$q$, 5, $q$The Euclidean algorithm finds gcd(a, b) by repeated division: divide a by b to get a remainder r, then replace (a, b) by (b, r) until the remainder is 0. The last non-zero remainder is the gcd. 84 = 2 x 36 + 12. 36 = 3 x 12 + 0. The last non-zero remainder is 12, so gcd(84, 36) = 12.$q$, $q$[{"t":"Idea of repeated division with remainders","m":2},{"t":"84 = 2 x 36 + 12","m":1},{"t":"36 = 3 x 12 + 0","m":1},{"t":"gcd = 12","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the Euclidean algorithm and use it to find the greatest common divisor of 84 and 36.$q$);
select course_code, count(*) as questions from public.theory_questions group by course_code order by course_code;
